<?php
require_once __DIR__ . '/_common.php';
$current_slug='data-anak'; require_once ROOT_PATH.'/includes/auth-guard.php';
$page_title='Data Anak'; $search=trim($_GET['search']??''); $pos=(int)($_GET['posyandu']??0);
$where=[];$params=[];if($search!==''){$where[]='(a.nama LIKE ? OR a.nik LIKE ? OR o.nama_ayah LIKE ? OR o.nama_ibu LIKE ?)';array_push($params,...array_fill(0,4,'%'.$search.'%'));}if($pos){$where[]='a.id_posyandu=?';$params[]=$pos;}
$sql='SELECT a.*,p.nama_posyandu,o.nama_ayah,o.nama_ibu,(SELECT COUNT(*) FROM pengukuran pg WHERE pg.id_anak=a.id_anak) AS jumlah_pengukuran FROM anak a JOIN posyandu p ON p.id_posyandu=a.id_posyandu JOIN orangtua o ON o.id_orangtua=a.id_orangtua'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.nama';$stmt=$pdo->prepare($sql);$stmt->execute($params);$anak_list=$stmt->fetchAll();$posyandu=$pdo->query('SELECT id_posyandu,nama_posyandu FROM posyandu ORDER BY nama_posyandu')->fetchAll();$flash=get_flash();
require ROOT_PATH.'/includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><h1 class="h3 mb-1">Data Anak</h1><p class="text-muted mb-0">Profil anak, orang tua/wali, dan riwayat pemantauan.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="<?= data_anak_url('ekspor.php') ?>"><i class="bi bi-file-earmark-spreadsheet me-1"></i>Ekspor Excel</a><a class="btn btn-outline-secondary" target="_blank" href="<?= data_anak_url('ekspor.php',['format'=>'print']) ?>"><i class="bi bi-file-earmark-pdf me-1"></i>Ekspor PDF</a><a class="btn btn-primary" href="<?= data_anak_url('tambah.php') ?>"><i class="bi bi-plus-lg me-1"></i>Tambah Anak</a></div></div>
<?php if($flash): ?><div class="alert alert-<?= e($flash['type']) ?> alert-dismissible fade show"><?= e($flash['message']) ?><button class="btn-close" data-bs-dismiss="alert"></button></div><?php endif; ?>
<div class="card"><div class="card-body"><form class="row g-2 mb-3"><div class="col-md-6"><input class="form-control" name="search" placeholder="Cari nama, NIK, atau orang tua..." value="<?= e($search) ?>"></div><div class="col-md-4"><select class="form-select" name="posyandu"><option value="">Semua posyandu</option><?php foreach($posyandu as $p): ?><option value="<?= (int)$p['id_posyandu'] ?>" <?= $pos===(int)$p['id_posyandu']?'selected':'' ?>><?= e($p['nama_posyandu']) ?></option><?php endforeach; ?></select></div><div class="col-md-2 d-grid"><button class="btn btn-outline-primary">Cari</button></div></form>
<div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Anak</th><th>NIK</th><th>Orang tua/wali</th><th>Posyandu</th><th>Pengukuran</th><th class="text-end">Aksi</th></tr></thead><tbody>
<?php if(!$anak_list): ?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada data yang cocok.</td></tr><?php endif; foreach($anak_list as $a): ?><tr><td><a class="fw-semibold text-decoration-none" href="<?= data_anak_url('detail.php',['id'=>$a['id_anak']]) ?>"><?= e($a['nama']) ?></a><div class="small text-muted"><?= $a['jenis_kelamin']==='L'?'Laki-laki':'Perempuan' ?> · <?= date('d/m/Y',strtotime($a['tanggal_lahir'])) ?></div></td><td><?= e($a['nik']) ?></td><td><?= e(implode(' / ',array_filter([$a['nama_ayah'],$a['nama_ibu']])) ?: '-') ?></td><td><?= e($a['nama_posyandu']) ?></td><td><?= (int)$a['jumlah_pengukuran'] ?></td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-primary" title="Detail" href="<?= data_anak_url('detail.php',['id'=>$a['id_anak']]) ?>"><i class="bi bi-eye"></i></a> <a class="btn btn-sm btn-outline-secondary" title="Ubah" href="<?= data_anak_url('edit.php',['id'=>$a['id_anak']]) ?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" title="Hapus" href="<?= data_anak_url('hapus.php',['id'=>$a['id_anak']]) ?>"><i class="bi bi-trash"></i></a></td></tr><?php endforeach; ?>
</tbody></table></div></div></div>
